  } else {
    task = SegmentTask::CreateCompactTask(CompactTask{
        path_, schema, current_group, allocate_segment_id_for_tmp_segment(),
        purge_deleted_docs ? filter : nullptr, !options_.enable_mmap_,
        concurrency});
  }
  tasks.push_back(task);
}

return tasks;

